const MOIS='janvier|février|mars|avril|mai|juin|juillet|août|septembre|octobre|novembre|décembre|janv\\.|févr\\.|avr\\.|juil\\.|sept\\.|oct\\.|nov\\.|déc\\.';
const JOUR='lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche';
const RE=new RegExp(`(?:(?:${JOUR}) )?\\d{1,2}(?:er)? (?:${MOIS})(?: \\d{4})?|(?:${MOIS}) \\d{4}|[-−+]?\\d+(?:[\\s\\u202f\\u00a0.,]\\d+)*`,'g');
const M_FR=['janvier','février','mars','avril','mai','juin','juillet','août','septembre','octobre','novembre','décembre'],M_AB=['janv.','févr.','mars','avr.','mai','juin','juil.','août','sept.','oct.','nov.','déc.'];
const J_FR=['lundi','mardi','mercredi','jeudi','vendredi','samedi','dimanche'];
const M_EN=['January','February','March','April','May','June','July','August','September','October','November','December'];
const J_EN=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'],J_VI=['thứ Hai','thứ Ba','thứ Tư','thứ Năm','thứ Sáu','thứ Bảy','Chủ nhật'];
const LANGS={fr:'FR',en:'EN',vi:'VI'};
let lang='fr';
try{lang=localStorage.getItem('appart-lang')||''}catch(e){}
if(!LANGS[lang]){const n=(navigator.language||'').toLowerCase();lang=n.startsWith('vi')?'vi':n.startsWith('en')?'en':'fr'}
const L=()=>lang==='en'?0:1;
const pats=PATS.map(([fr,en,vi])=>{const names=[];const src='^'+fr.replace(/[.*+?^${}()|[\]\\]/g,'\\$&').replace(/\\\{([ab])\\\}/g,(m,k)=>{names.push(k);return '(.+?)'})+'$';return{re:new RegExp(src),names,t:[en,vi]}});
function trDate(t){const w=t.split(' ');let wd=null,d=null,m=null,y=null;
 for(const x of w){const j=J_FR.indexOf(x);if(j>=0){wd=j;continue}let k=M_FR.indexOf(x);if(k<0)k=M_AB.indexOf(x);if(k>=0){m=k;continue}if(/^\d{4}$/.test(x))y=x;else if(/^\d{1,2}(er)?$/.test(x))d=parseInt(x)}
 if(m==null)return t;
 if(lang==='en')return[wd!=null?J_EN[wd]:'',d!=null?d:'',M_EN[m],y||''].filter(v=>v!=='').join(' ');
 return[wd!=null?J_VI[wd]:'',d!=null?d:'','tháng '+(m+1),y?'năm '+y:''].filter(v=>v!=='').join(' ')}
function trNum(t){if(!/\d/.test(t)||/[a-zé]/i.test(t))return t;const sign=/^[-−+]/.test(t)?t[0]:'';const body=t.slice(sign.length);
 const ci=body.lastIndexOf(',');const intp=ci>=0?body.slice(0,ci):body,dec=ci>=0?body.slice(ci+1):'';
 const parts=intp.split(/[\s  ]/);const grouped=parts.length>1&&parts.slice(1).every(p=>/^\d{3}$/.test(p));
 const ip=grouped?parts.join(lang==='en'?',':'.'):intp;return sign+ip+(ci>=0?(lang==='en'?'.':',')+dec:'')}
const tok=t=>/[a-zé]/i.test(t)?trDate(t):trNum(t);
const fill=(tpl,toks)=>tpl.replace(/\{(\d+)\}/g,(m,i)=>toks[+i]!=null?tok(toks[+i]):m);
function tr(s){const m=/^(\s*)([\s\S]*?)(\s*)$/.exec(s);const core=m[2].replace(/\s+/g,' ');if(!core)return null;
 let out=tr1(core);
 if(out==null&&/ : | · |, /.test(core)){const parts=core.split(/( : | · |, )/);let hit=false;
  const res=parts.map((x,i)=>{if(i%2)return x===' : '?': ':x;const t=tr1(x);if(t!=null&&t!==x)hit=true;return t??x});if(hit)out=res.join('')}
 return out==null?null:m[1]+out+m[3]}
function tr1(core){
 const toks=[];let i=0;const key=core.replace(RE,x=>{toks.push(x);return '{'+(i++)+'}'});
 let out=null;const d=DICT[key];
 if(d)out=fill(d[L()],toks);
 else{for(const p of pats){const r=p.re.exec(key);if(r){let t=p.t[L()];p.names.forEach((k,j)=>{t=t.split('{'+k+'}').join(r[j+1])});out=fill(t,toks);break}}}
 if(out==null&&toks.length&&!/[A-Za-zÀ-ÿ]/.test(key.replace(/\{\d+\}/g,'').replace(/m²|\b(km|m|h|k)\b/g,'')))out=fill(key,toks);
 return out}
